-- The sheet's claim templates: a name (trimmed, at most once per sheet), an amount and a note. Saving a name again
-- replaces its amount and note. A claim made from a template copies them, so a later save does not alter it.
CREATE TABLE claim_template (
    sheet_id VARCHAR(255) NOT NULL,
    name VARCHAR(255) NOT NULL,
    amount DECIMAL(19, 2) NOT NULL,
    note VARCHAR(1000) NOT NULL,
    listed BIGINT NOT NULL,
    PRIMARY KEY (sheet_id, name)
);
# GET /api/sheets/{sheetId}/templates — the sheet's claim templates, in the order first saved ({name, amount, note}).
respond:
  class: net.officefloor.hq.app.template.RespondWithTemplates
  govern: [ readonly-transaction ]
# POST /api/sheets/{sheetId}/templates — saves a claim template. Body {"name":"...","amount":"12.50","note":"..."}; name
# and note trimmed. Saving a name again replaces that template. A blank name, or an amount the claim form would refuse,
# is refused with 422 and nothing is stored or recorded.
viewer:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: archived
  govern: [ transaction ]
